/* HEXA BATTLEGROUNDS setup — PART 35 OF 80. Run parts in order. Safe to re-run. */ create or replace function host_command(p_token text, p_arena uuid, p_cmd text, p_args jsonb default '{}'::jsonb, p_reason text default null) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; v_ids uuid[]; v_id uuid; v_out jsonb := '{}'::jsonb; v_err text; v_res jsonb; v_delta interval; v_logargs jsonb; v_all_ok text[] := array['open_boarding','assign_buses','drive','finalize_roles','pause','resume','broadcast','clear_overlay', 'blackout','countdown','story','bargain','zone_warn','zone_now','zone_cancel','zone_set','spawn_airdrop','begin_finale', 'finale_stage','launch_sync','close_sync','lock_results','reveal_winner','end_game','reveal_squad00', 'next_phase','set_phase','hide_rankings','red_zone','red_cancel','start_match','autopilot_on','autopilot_off', 'lock_next','lock_building','unlock_all','final_lockdown','spawn_loot']; v_new text[] := array['set_phase','next_phase','hide_rankings','reset_pin','red_zone','red_cancel']; begin v_ev := _auth_host(p_token); p_args := coalesce(p_args, '{}'::jsonb); v_logargs := p_args - 'pin'; if p_arena is null then if p_cmd = any(v_all_ok) then select array_agg(id order by number) into v_ids from arenas where event_id = v_ev; else v_ids := array[null::uuid]; end if; else if not exists (select 1 from arenas where id = p_arena and event_id = v_ev) then raise exception 'BAD_ARENA'; end if; v_ids := array[p_arena]; end if; foreach v_id in array v_ids loop begin v_delta := null; if p_cmd = 'resume' then select now() - paused_at into v_delta from arenas where id = v_id and paused; end if; if p_cmd in ('open_boarding', 'assign_buses', 'drive', 'start_match') and v_id is not null and not exists (select 1 from teams where arena_id = v_id and ready) then raise exception 'NO_READY_SQUADS'; end if; if p_cmd = any(v_new) then v_res := _host_exec_p0(v_ev, v_id, p_cmd, p_args, p_reason); elsif p_cmd in ('start_match', 'autopilot_on') then if p_cmd = 'start_match' then if coalesce(p_args ->> 'length', 'standard') not in ('quick', 'standard', 'full') then raise exception 'BAD_LENGTH'; end if; update events set settings = settings || _auto_preset(p_args ->> 'length') where id = v_ev; else update events set settings = settings || jsonb_build_object('auto_pacing', 1) where id = v_ev; end if; update arenas set autopilot = true, auto_length = coalesce(p_args ->> 'length', auto_length, 'standard'), auto_story = case when phase in ('lobby', 'boarding', 'shuttle', 'roles') then -1 when phase = 'play' then greatest(auto_story, match_phase) else auto_story end where id = v_id; perform _auto_resync(v_id); if (select phase from arenas where id = v_id) = 'play' then perform _set_match_phase(v_id, (select match_phase from arenas where id = v_id)); end if; perform _tick(v_id, true); v_res := _auto_status(v_id); elsif p_cmd in ('lock_next', 'lock_building') then if (select phase from arenas where id = v_id) not in ('play', 'finale') then raise exception 'WRONG_PHASE'; end if; v_res := jsonb_build_object('lockdown', _lock_next(v_id, case when p_cmd = 'lock_building' then p_args ->> 'building' end, case when p_cmd = 'lock_building' then (p_args ->> 'level')::int end)); if v_res ->> 'lockdown' is null then raise exception 'NOTHING_LEFT_TO_SEAL'; end if; if coalesce((p_args ->> 'now')::boolean, false) then perform _lock_seal((v_res ->> 'lockdown')::uuid); end if; elsif p_cmd = 'unlock_all' then delete from lockdowns where arena_id = v_id; perform _lock_publish(v_id); perform _feed(v_id, 'lockdown.lifted', '{}'::jsonb); v_res := '{}'::jsonb; elsif p_cmd = 'final_lockdown' then if (select phase from arenas where id = v_id) <> 'finale' then raise exception 'WRONG_PHASE'; end if; perform _final_lockdown(v_id); v_res := '{}'::jsonb; elsif p_cmd = 'spawn_loot' then if (select phase from arenas where id = v_id) <> 'play' then raise exception 'WRONG_PHASE'; end if; v_res := jsonb_build_object('spawned', _spawn_pickups(v_id)); elsif p_cmd = 'autopilot_off' then update arenas set autopilot = false, auto_next_at = null, overlay = overlay - 'auto' where id = v_id; v_res := '{}'::jsonb; elsif p_cmd = 'clear_overlay' then update arenas set overlay = (select coalesce(jsonb_object_agg(k, v), '{}'::jsonb) from jsonb_each(overlay) as x(k, v) where k in ('match', 'zone', 'world', 'red', 'auto', 'lock')) where id = v_id; v_res := '{}'::jsonb; else v_res := _host_exec(v_ev, v_id, p_cmd, p_args, p_reason); end if; if p_cmd = 'resume' and v_delta is not null then update lockdowns set seal_at = seal_at + v_delta where arena_id = v_id and not sealed; perform _lock_publish(v_id); update arenas set phase_next_at = phase_next_at + v_delta, phase_started_at = phase_started_at + v_delta, auto_next_at = auto_next_at + v_delta, last_red_at = last_red_at + v_delta, red_at = red_at + v_delta, last_lock_at = last_lock_at + v_delta, last_pickup_at = last_pickup_at + v_delta, shuttle_departed_at = shuttle_departed_at + v_delta, overlay = case when overlay ? 'match' and overlay #>> '{match,next_at}' is not null then jsonb_set(overlay, '{match,next_at}', to_jsonb((overlay #>> '{match,next_at}')::timestamptz + v_delta)) else overlay end where id = v_id; elsif p_cmd = 'begin_finale' then update arenas set match_phase = 5, phase_started_at = now(), phase_next_at = null, overlay = overlay || jsonb_build_object('match', jsonb_build_object('phase', 5, 'started_at', now(), 'next_at', null, 'zone_target', 5)) where id = v_id; perform _feed(v_id, 'phase.started', jsonb_build_object('phase', 5)); elsif p_cmd = 'zone_cancel' then update arenas set zone_hold = true where id = v_id; elsif p_cmd in ('zone_warn', 'zone_now', 'zone_set') then update arenas set zone_hold = false where id = v_id; elsif p_cmd = 'reset_arena' then update arenas set match_phase = 0, phase_started_at = null, phase_next_at = null, zone_hold = false, red_x = null, red_y = null, red_r = null, red_at = null, last_red_at = null, autopilot = false, auto_step = null, auto_next_at = null, auto_story = -1, last_lock_at = null, last_pickup_at = null, overlay = overlay - 'auto' - 'lock' where id = v_id; update teams set zone_hit_at = null, travel_fx = null, travel_fy = null, level = 0, bldg = null, vel_x = 0, vel_y = 0 where arena_id = v_id; delete from lockdowns where arena_id = v_id; delete from pickups where arena_id = v_id; end if; v_out := v_out || jsonb_build_object(coalesce(v_id::text, 'event'), v_res); insert into audit_log(event_id, arena_id, actor, action, args, reason) values (v_ev, v_id, 'host', p_cmd, v_logargs, p_reason); exception when others then v_err := sqlerrm; insert into audit_log(event_id, arena_id, actor, action, args, reason, ok, error) values (v_ev, v_id, 'host', p_cmd, v_logargs, p_reason, false, v_err); if array_length(v_ids, 1) = 1 then return jsonb_build_object('ok', false, 'error', v_err); end if; v_out := v_out || jsonb_build_object(coalesce(v_id::text, 'event'), jsonb_build_object('error', v_err)); end; if v_id is not null then perform _zone_publish(v_id); perform _ping_arena(v_id, 'host'); end if; end loop; return jsonb_build_object('ok', true, 'result', v_out); end $$; drop function if exists captain_steer(text, double precision, double precision); create or replace function captain_steer(p_token text, p_x float8, p_y float8, p_vx float8 default 0, p_vy float8 default 0) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; a arenas; cur float8[]; dt float8; maxd float8; d float8; nx float8; ny float8; v_loc text; v_others int; v_ping boolean; b buildings; v_spd float8; v_vx float8; v_vy float8; v_vm float8; v_pick jsonb; v_wall text; begin p := _auth_captain(p_token); select * into t from teams where id = p.team_id for update; select * into a from arenas where id = t.arena_id; if a.phase <> 'play' then raise exception 'NO_MOVES_NOW'; end if; if t.state = 'recovery' then raise exception 'BUSY'; end if; if exists (select 1 from mission_instances where team_id = t.id and status = 'active' and kind = 'battle') then raise exception 'IN_BATTLE'; end if; if p_x is null or p_y is null or p_x = 'NaN'::float8 or p_y = 'NaN'::float8 or abs(p_x) = 'Infinity'::float8 or abs(p_y) = 'Infinity'::float8 then raise exception 'BAD_REQUEST'; end if; cur := _team_xy(t); v_spd := _cfg(t.event_id, 'move_speed') / 1000.0; dt := least(4, greatest(0, extract(epoch from now() - coalesce(case when t.state = 'traveling' then now() else t.pos_at end, now() - interval '1 second')))); if t.state = 'traveling' then dt := 0.25; end if; maxd := v_spd * dt * 1.25 + 0.003; nx := greatest(0.02, least(0.98, p_x)); ny := greatest(0.02, least(0.98, p_y)); d := sqrt((nx - cur[1]) ^ 2 + (ny - cur[2]) ^ 2); if d > maxd then nx := cur[1] + (nx - cur[1]) * maxd / d; ny := cur[2] + (ny - cur[2]) * maxd / d; end if; if t.level > 0 then select * into b from buildings where id = t.bldg; if b.id is not null then nx := greatest(b.x0 + 0.004, least(b.x1 - 0.004, nx)); ny := greatest(b.y0 + 0.004, least(b.y1 - 0.004, ny)); end if; else select bb.id into v_wall from buildings bb where nx between bb.x0 and bb.x1 and ny between bb.y0 and bb.y1 and _sealed(t.arena_id, bb.id, 0) and not (cur[1] between bb.x0 and bb.x1 and cur[2] between bb.y0 and bb.y1) limit 1; if v_wall is not null then nx := cur[1]; ny := cur[2]; end if; end if; v_vx := coalesce(p_vx, 0); v_vy := coalesce(p_vy, 0); if v_vx = 'NaN'::float8 or v_vy = 'NaN'::float8 or abs(v_vx) = 'Infinity'::float8 or abs(v_vy) = 'Infinity'::float8 then v_vx := 0; v_vy := 0; end if; v_vm := sqrt(v_vx ^ 2 + v_vy ^ 2); if v_vm > v_spd * 1.1 then v_vx := v_vx * v_spd * 1.1 / v_vm; v_vy := v_vy * v_spd * 1.1 / v_vm; end if; if v_wall is not null then v_vx := 0; v_vy := 0; end if; v_loc := _loc_at3(t.arena_id, t.event_id, nx, ny, t.level, t.bldg); if v_loc is distinct from t.location_id then update mission_instances set status = 'cancelled' where team_id = t.id and status = 'active' and kind in ('mission', 'relay', 'airdrop') and sync_round_id is null; end if; v_ping := v_loc is distinct from t.location_id or t.last_steer_ping is null or t.last_steer_ping < now() - interval '2 seconds'; update teams set pos_x = nx, pos_y = ny, pos_at = now(), vel_x = v_vx, vel_y = v_vy, dropped = true, location_id = v_loc, state = 'idle', travel_to = null, travel_from = null, travel_started_at = null, travel_arrive_at = null, visit_missions = case when v_loc is distinct from t.location_id then 0 else visit_missions end, last_steer_ping = case when v_ping then now() else last_steer_ping end where id = t.id; if v_loc is not null and v_loc is distinct from t.location_id then if t.jammed_until is null or t.jammed_until < now() then perform _feed(t.arena_id, 'squad.arrived', jsonb_build_object('team', t.number, 'location', v_loc)); end if; select count(*) into v_others from teams x where x.arena_id = t.arena_id and x.ready and x.id <> t.id and x.location_id = v_loc; if v_others > 0 then perform _feed(t.arena_id, 'encounter.detected', jsonb_build_object('location', v_loc, 'squads', v_others + 1)); perform _ping_arena(t.arena_id, 'encounter'); end if; end if; v_pick := _take_pickups(t.id, nx, ny); if v_ping or v_pick is not null then perform _ping_team(t.id, 'move'); end if; return jsonb_build_object('x', nx, 'y', ny, 'location', v_loc, 'level', t.level, 'clamped', abs(nx - p_x) > 0.0005 or abs(ny - p_y) > 0.0005, 'wall', v_wall, 'picked', v_pick); end $$; create or replace function captain_move(p_token text, p_location text) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; a arenas; l locations; v_secs numeric; cur float8[]; d float8; begin p := _auth_captain(p_token); select * into t from teams where id = p.team_id for update; select * into a from arenas where id = t.arena_id; if a.phase <> 'play' then raise exception 'NO_MOVES_NOW'; end if; if t.state = 'recovery' then raise exception 'BUSY'; end if; if exists (select 1 from mission_instances where team_id = t.id and status = 'active' and kind = 'battle') then raise exception 'IN_BATTLE'; end if; select * into l from locations where id = p_location; if l.id is null or l.kind = 'start' or not l.enabled then raise exception 'BAD_LOCATION'; end if; if l.id = t.location_id and t.state = 'idle' then raise exception 'ALREADY_HERE'; end if; if l.kind <> 'stairs' and l.building is not null and _sealed(t.arena_id, l.building, l.level) then raise exception 'SEALED'; end if; if l.kind = 'stairs' and _sealed(t.arena_id, l.building, 0) then raise exception 'SEALED'; end if; if not t.dropped and l.level > 0 then raise exception 'DROP_OUTSIDE'; end if; if t.dropped and (l.level <> t.level or (l.level > 0 and l.building is distinct from t.bldg)) then raise exception 'TAKE_THE_STAIRS'; end if; cur := _team_xy(t); d := sqrt((l.x - cur[1]) ^ 2 + (l.y - cur[2]) ^ 2); if not t.dropped then v_secs := _cfg(t.event_id, 'drop_seconds'); else v_secs := greatest(1, round((d / (_cfg(t.event_id, 'move_speed') / 1000.0))::numeric, 1)); end if; update mission_instances set status = 'cancelled' where team_id = t.id and status = 'active' and kind in ('mission', 'relay', 'airdrop') and sync_round_id is null; update teams set state = 'traveling', travel_from = location_id, travel_to = l.id, travel_started_at = now(), travel_arrive_at = now() + _secs(v_secs), travel_fx = cur[1], travel_fy = cur[2], pos_x = cur[1], pos_y = cur[2], pos_at = now() where id = t.id; if t.jammed_until is null or t.jammed_until < now() then perform _feed(t.arena_id, 'squad.movement.started', jsonb_build_object('team', t.number, 'from', t.location_id, 'to', l.id)); end if; perform _ping_team(t.id, 'move'); perform _ping_arena(t.arena_id, 'move'); return jsonb_build_object('arrive_at', now() + _secs(v_secs), 'seconds', v_secs); end $$; create or replace function captain_explore(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; v_id uuid; begin p := _auth_captain(p_token); select * into t from teams where id = p.team_id for update; if (select phase from arenas where id = t.arena_id) <> 'play' then raise exception 'NO_MOVES_NOW'; end if; if t.state <> 'idle' then raise exception 'BUSY'; end if; if t.location_id is null then raise exception 'NOT_AT_LOCATION'; end if; if (select kind from locations where id = t.location_id) = 'stairs' then raise exception 'NOTHING_HERE'; end if; if exists (select 1 from mission_instances where team_id = t.id and status = 'active' and kind <> 'battle') then raise exception 'MISSION_ACTIVE'; end if; if t.visit_missions >= _cfg(t.event_id, 'visit_missions') then raise exception 'AREA_EXHAUSTED'; end if; v_id := _start_location_mission(t.id); if v_id is null then raise exception 'NO_MISSIONS'; end if; return jsonb_build_object('instance', v_id); end $$; create or replace function _fail(p_instance uuid, p_status text default 'failed') returns void language plpgsql as $$ declare mi mission_instances; t teams; b battles; begin select * into mi from mission_instances where id = p_instance for update; if mi.status <> 'active' then return; end if; update mission_instances set status = p_status where id = mi.id; select * into t from teams where id = mi.team_id; if mi.kind = 'battle' then select * into b from battles where id = mi.battle_id; if not exists (select 1 from mission_instances where battle_id = mi.battle_id and status = 'active') then perform _resolve_battle(mi.battle_id, null); end if; elsif mi.kind = 'recovery' then perform _respawn(mi.team_id, 'bounded'); elsif mi.sync_round_id is null and mi.kind in ('mission', 'relay') then perform _damage(mi.team_id, _cfg(t.event_id, 'dmg_fail'), 'mission_fail', mi.id::text, 'Challenge not solved'); elsif mi.sync_round_id is null and mi.kind = 'airdrop' and p_status in ('failed', 'expired') then perform _damage(mi.team_id, _cfg(t.event_id, 'dmg_airdrop_fail'), 'airdrop_fail', mi.id::text, 'Crate not cracked'); end if; perform _feed(t.arena_id, 'mission.failed', jsonb_build_object('team', t.number)); perform _ping_team(mi.team_id, 'result'); end $$;
